// L19: letters, pitches, personalities and engine messages generated by the engine are in English.
import { describe, expect, it } from "vitest";
import {
  BrainError, MockBrain, MockChain, PROFESSIONS, createJournal, createRng, loadConfig,
  type Brain, type BrainRequest, type BrainResponse, type DarwinEvent, type Deps,
} from "../shared/index.ts";
import { looksEnglish } from "../brain/english-check.ts";
import { createEngine } from "./index.ts";
import { TRAITS, basePersonality, createFounderGenome, personalityWith } from "./genome.ts";
import { StubMarket } from "./stub-market.ts";

const FR = /\b(le|la|les|des|une|est|pour|avec|sur|dans|tu|je|vous|votre|cher|enfant|mais)\b|[éèàêôùç]/i;

/** Recording brain: delegates to MockBrain (optionally failing letters or forcing the bid text) and keeps every request. */
class SpyBrain implements Brain {
  readonly kind: "mock" | "nearai";
  readonly inner = new MockBrain();
  readonly requests: BrainRequest[] = [];
  constructor(kind: "mock" | "nearai" = "mock", private failLetters = false, private bidText?: string) { this.kind = kind; }
  listModels() { return this.inner.listModels(); }
  defaultModel() { return this.inner.defaultModel(); }
  async complete(req: BrainRequest): Promise<BrainResponse> {
    this.requests.push(req);
    if (this.failLetters && req.purpose === "letter") throw new BrainError("TIMEOUT", "timeout");
    const r = await this.inner.complete(req);
    return req.purpose === "bid" && this.bidText ? { ...r, text: this.bidText } : r;
  }
}

async function run(brain: Brain, ticks = 40) {
  const config = loadConfig({ DARWIN_PRESET: "demo", DARWIN_SEED: "42" });
  let t = 0;
  const now = () => new Date(Date.UTC(2026, 10, 12) + ++t);
  const journal = createJournal({ now });
  const deps: Deps = { config, chain: new MockChain({ now }), brain, journal, rng: createRng(42), now };
  const engine = createEngine(deps, new StubMarket(deps), { autoRun: false });
  await engine.start();
  for (let i = 0; i < ticks && engine.getState().running; i++) await engine.tick();
  const events: DarwinEvent[] = journal.since(0, 1e7);
  return { engine, events };
}

describe("genome texts", () => {
  it("base personalities and traits are English", () => {
    for (const p of PROFESSIONS) { expect(basePersonality(p)).not.toMatch(FR); expect(basePersonality(p)).toMatch(/^You are a freelance/); }
    for (const t of TRAITS) { expect(t).not.toMatch(FR); expect(t).toMatch(/^You are /); }
    expect(personalityWith("logo", TRAITS[0])).toContain(" Trait: ");
  });
  it("founder genomes carry an English personality", () => {
    const rng = createRng(1);
    for (let i = 0; i < 6; i++) expect(createFounderGenome(rng, i, ["mock/small"]).personality).not.toMatch(FR);
  });
});

describe("letters", () => {
  it("mock run: every letter is written in English and the prompt carries the rule", async () => {
    const brain = new SpyBrain();
    const { engine, events } = await run(brain);
    const letters = engine.getState().letters;
    expect(letters.length).toBeGreaterThan(0);
    for (const l of letters) {
      expect(l.text.startsWith("[mock] Dear child")).toBe(true);
      expect(looksEnglish(l.text)).toBe(true);
    }
    expect(events.filter((e) => e.type === "letter.written")).toHaveLength(letters.length);
    const reqs = brain.requests.filter((r) => r.purpose === "letter");
    expect(reqs.length).toBe(letters.length);
    for (const r of reqs) {
      expect(r.messages.map((m) => m.content).join("\n")).toContain("Always answer in English.");
      expect(looksEnglish(r.messages.at(-1)!.content)).toBe(true);
    }
  });

  it("brain failure: English fallback letter and English warning", async () => {
    const { engine, events } = await run(new SpyBrain("mock", true));
    const letters = engine.getState().letters;
    expect(letters.length).toBeGreaterThan(0);
    for (const l of letters) { expect(l.text.startsWith("[fallback] Dear ")).toBe(true); expect(l.text).not.toMatch(FR); }
    const w = events.filter((e) => e.type === "system.warning").map((e) => (e.data as { message: string }).message);
    expect(w.some((m) => m.startsWith("Fallback letter (brain unavailable)"))).toBe(true);
    for (const m of w) expect(m).not.toMatch(FR);
  });
});

describe("pitches and engine texts", () => {
  it("mock pitches are English", async () => {
    const { events } = await run(new SpyBrain(), 14);
    const pitches = events.filter((e) => e.type === "bid.placed").map((e) => (e.data as { bid: { pitch: string } }).bid.pitch);
    expect(pitches.length).toBeGreaterThan(3);
    for (const p of pitches) expect(p).not.toMatch(FR);
  });

  it("real-mode pitch: the prompt carries the rule, a French answer is replaced by an English fallback", async () => {
    const brain = new SpyBrain("nearai", false, "Je ferai le travail pour vous et je livrerai le résultat dans les délais que vous souhaitez pour cette tâche.");
    const { events } = await run(brain, 14);
    const bidReqs = brain.requests.filter((r) => r.purpose === "bid");
    expect(bidReqs.length).toBeGreaterThan(0);
    for (const r of bidReqs) expect(r.messages[0]!.content).toContain("Always answer in English.");
    const pitches = events.filter((e) => e.type === "bid.placed").map((e) => (e.data as { bid: { pitch: string } }).bid.pitch);
    expect(pitches.length).toBeGreaterThan(0);
    for (const p of pitches) expect(p).not.toMatch(FR);
  });

  it("execution prompts carry the rule and tasks posted by the engine are English", async () => {
    const brain = new SpyBrain();
    const { events } = await run(brain, 14);
    const exec = brain.requests.filter((r) => r.purpose === "execute_task");
    expect(exec.length).toBeGreaterThan(0);
    for (const r of exec) expect(r.messages[0]!.content).toContain("Always answer in English.");
    const titles = events.filter((e) => e.type === "task.posted").map((e) => (e.data as { task: { title: string } }).task.title);
    for (const t of titles) expect(t).not.toMatch(FR);
  });
});
